import { mkdtemp, readFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

import { DuckDBInstance } from '@duckdb/node-api';

const outDir = await mkdtemp(join(tmpdir(), 'nao-write-probe-'));
const forbiddenDir = await mkdtemp(join(tmpdir(), 'nao-forbidden-'));

const instance = await DuckDBInstance.create(':memory:');
const connection = await instance.connect();

await connection.run(`SET allowed_directories = ['${outDir}']`);
await connection.run('SET enable_external_access = false');
await connection.run('SET lock_configuration = true');

const target = join(outDir, 'out.csv');
const forbidden = join(forbiddenDir, 'leak.csv');

async function attempt(label, sql) {
	try {
		await connection.run(sql);
		console.log(`${label}: OK`);
	} catch (error) {
		console.log(`${label}: BLOCKED -> ${error.message.split('\n')[0]}`);
	}
}

await attempt('COPY TO inside allowed dir', `COPY (SELECT 1 AS a, 'x' AS b) TO '${target}' (FORMAT csv, HEADER)`);
await attempt('COPY TO parquet inside allowed dir', `COPY (SELECT 1 AS a) TO '${join(outDir, 'out.parquet')}' (FORMAT parquet)`);
await attempt('COPY TO outside allowed dir', `COPY (SELECT 1 AS a) TO '${forbidden}' (FORMAT csv)`);
await attempt('COPY TO partitioned dir', `COPY (SELECT 1 AS a, 'eu' AS r) TO '${join(outDir, 'parts')}' (FORMAT parquet, PARTITION_BY r)`);
await attempt('ATTACH a new db file inside allowed dir', `ATTACH '${join(outDir, 'side.duckdb')}'`);
await attempt('widen allowlist', `SET allowed_directories = ['${forbiddenDir}']`);

try {
	console.log('file contents:', JSON.stringify(await readFile(target, 'utf-8')));
} catch (error) {
	console.log('file contents: unreadable ->', error.message);
}

connection.closeSync();
instance.closeSync();

